        key = (*buyer, inquiry.listing_id)
        if key not in kept:
            kept[key] = inquiry.reference
            continue
        History.objects.create(
            inquiry=inquiry,
            from_status=inquiry.status,
            to_status="cancelled",
            reason=f"Closed automatically as a duplicate of {kept[key]}.",
        )
        inquiry.status = "cancelled"
        inquiry.save(update_fields=["status", "updated_at"])


